INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('owdlhr7bbl4wul7dkvowdlhr6xuprvdl', '2025-Q3', 'Out/2025', '2025-10-06T12:53'::timestamptz, 'Joao Victor Cardoso De Moraes', 'joao victor cardoso de moraes', 'PHARUS', 'Rodrigo Lunardi', 9.0, 'Promotor', 9.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Tenho clareza e estou executando com consistência', 'Acredito muito no conhecimento técnico transmitido pelos profissionais envolvidos. Como a parceria é recente e os resultados naturalmente lentos, ainda tenho uma ponta de insegurança', NULL, 'O entendimento transmitido sobre construção de riqueza. Acredito que poderia ter mais aulas pra aumentar a compreensão', 'Resultados rápidos e um fluxo de capital maior do que eu faço atualmente', 'Estou um pouco inseguro com o processo. Parecia que a estratégia dos consórcios seria mais rápida (sei que não é bem assim, mas expectativa criada foi maior). Algumas oportunidades de investimento ocorrem apenas dentro da plataforma da quartavia e isso me deixa inseguro e de certa forma dependente demais do sistema. Meu ganho mensal com meu trabalho parece estar aquém de deixar tranquilo para que eu possa fazer dívidas boas, não me sinto confiante em fazer tantos compromissos financeiros', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'owdlhr7bbl4wul7dkvowdlhr6xuprvdl', 'cadastro 2026-T2 (281 dias)', 'cadastro 2026-T2') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = 