INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('xzz23bnjlkxpmedypjvxzz2j1fg0jd1u', '2025-Q4', 'Dez/2025', '2025-12-11T16:46'::timestamptz, 'Eduardo Alencar Thomaziello', 'eduardo alencar thomaziello', 'PHARUS', 'Gabriel Oliveira', 10.0, 'Promotor', 10.0, 10.0, 5.0, NULL, 'Sim, totalmente', NULL, NULL, NULL, NULL, NULL, 'A orientação que recebo é muito efetiva para a formação do patrimônio que pretendo criar até minha aposentadoria daqui 8 anos', 'Eu escolhi ficar mais 3 anos sem hesitar. Com os resultados esperados alcançados daqui um ano eu não hesitarei ficar mais tempo', 'Eu vi que há conteúdo novo que ainda não assisti, mas que estava aguardando. Creio que vai me clarear muito mais no caminho que estamos trilhando', NULL, NULL, 'nova jornada (backoffice/QV360)', 'NPS_Q4_2025_ENVIADO_DEZEMBRO.xlsx', 'pharus', 'xzz23bnjlkxpmedypjvxzz2j1fg0jd1u', 'aba PHARUS da planilha', 'NPS (PHARUS)') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_